args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-28-batch-six/spatial');C<-file.path(P,'biofigure/benchmark/library/spatial/squidpy-seqfish-neighborhood-20261028')
suppressPackageStartupMessages({library(hdf5r);library(deldir);library(jsonlite);library(digest)})
f<-H5File$new(file.path(C,'data/raw/seqfish.h5ad'),'r'); xy<-t(f[['obsm/spatial']]$read()); ids<-f[['obs/_index']]$read();categories<-f[['obs/__categories/celltype_mapped_refined']]$read();cl<-as.integer(f[['obs/celltype_mapped_refined']]$read())+1L;f$close_all()
stopifnot(nrow(xy)==19416L,length(unique(ids))==19416L,all(is.finite(xy)),!anyDuplicated(data.frame(xy)),length(categories)==22L,all(cl%in%1:22))
d<-data.frame(cell_id=ids,source_x=xy[,1],source_y=xy[,2],cell_type=categories[cl],category_index=cl-1L,plot_x=xy[,2],plot_y=xy[,1])
tri<-deldir(xy[,1],xy[,2],suppressMsge=TRUE)$delsgs;e<-unique(data.frame(i=pmin(tri$ind1,tri$ind2),j=pmax(tri$ind1,tri$ind2)));e<-e[order(e$i,e$j),];stopifnot(!any(e$i==e$j),!anyDuplicated(e),max(c(e$i,e$j))<=nrow(d))
count<-function(x){z<-tabulate(x[e$i]+22L*(x[e$j]-1L),484L);m<-matrix(z,22,22);m+t(m)}
observed<-count(cl);set.seed(20261028);perms<-replicate(1000,as.vector(count(sample(cl))));mu<-rowMeans(perms);sdpop<-sqrt(rowMeans((perms-mu)^2));z<-matrix((as.vector(observed)-mu)/sdpop,22,22,dimnames=list(categories,categories));stopifnot(all(is.finite(z)),isSymmetric(z),all(diag(observed)%%2==0),sum(observed)==2*nrow(e))
hc<-hclust(dist(z),method='ward.D2')
write.csv(d,file.path(C,'results/plot_data/cells.csv'),row.names=FALSE);write.csv(transform(e,source_id=ids[i],target_id=ids[j]),file.path(C,'results/plot_data/delaunay-edges.csv'),row.names=FALSE)
write.csv(data.frame(cell_type=categories,n=tabulate(cl,22L)),file.path(C,'results/plot_data/category-counts.csv'),row.names=FALSE)
write.csv(z,file.path(C,'results/plot_data/neighborhood-zscore.csv'));write.csv(observed,file.path(C,'results/plot_data/neighborhood-observed-counts.csv'))
q<-list(n_cells=nrow(d),n_genes=351,n_categories=22,n_undirected_edges=nrow(e),no_self_loops=TRUE,no_duplicate_edges=TRUE,unique_ids=TRUE,coordinates_unmodified=TRUE,source_coordinate_units='source centered/scaled spatial coordinates; physical micrometres not asserted',display_transform='x=source_y,y=source_x; rigid axis exchange only, as landscape paper view',graph_engine=paste('deldir',packageVersion('deldir')),graph_scope='Delaunay no radius pruning; unweighted symmetric adjacency with no diagonal, same author rule; degenerate-boundary triangulation may differ from SciPy/Qhull',seed=20261028,n_permutations=1000,permutation_sd='population SD, ddof=0 as NumPy std',label_counts=as.list(table(d$cell_type)),category_order=categories[hc$order],source_h5ad_sha256=digest(file=file.path(C,'data/raw/seqfish.h5ad'),algo='sha256'),zscore_range=range(z),author_statistics_recomputed_in_R=TRUE,original_zscores_not_available=TRUE)
write_json(q,file.path(W,'data-qc.json'),pretty=TRUE,auto_unbox=TRUE);saveRDS(list(cells=d,edges=e,z=z,observed=observed,hc=hc,categories=categories,qc=q),file.path(W,'computations.rds'));writeLines(capture.output(sessionInfo()),file.path(C,'data/metadata/sessionInfo.txt'))
print(q[c('n_cells','n_categories','n_undirected_edges','zscore_range')])
